"""Add eight original Spring testing-isolation lessons to local fixtures."""
import copy
import datetime
import html
import json
import pathlib
import re
import uuid

root=pathlib.Path(__file__).resolve().parents[1]
fixture=root/'src/data/fixtures.json'
rows=json.loads(fixture.read_text())
by_path={row['path']:row for row in rows}
stamp=datetime.datetime.now(datetime.UTC).isoformat()

def prose(value):
    return re.sub(r'\[\[([^|]+)\|([^\]]+)\]\]',lambda match:'<a href="/'+match[1]+'">'+match[2]+'</a>',html.escape(value))

lessons=[
 dict(slug='webmvctest-slice-collaborators',title='Spring @WebMvcTest: replace collaborators without claiming a full application',summary='An MVC slice checks controller mapping and serialization with selected web components; service and database behavior need separate tests.',blocks=[
  ('What the slice owns','A receipt controller accepts JSON, validates a command and delegates to ReceiptService. @WebMvcTest(ReceiptController.class) loads the MVC slice for that controller, not the repository graph, migration runner or remote payment client. Supply a mock service through the current Spring test bean-override mechanism and assert the HTTP contract. [[spring/mockmvc-standalone-scope|Standalone MockMvc]] assembles an even smaller setup; [[spring/mockmvc-tests|application-backed MockMvc]] can cover more wiring.'),
  ('Avoid accidental production claims','An OK response from a mocked service proves the controller produced the right status and body for that supplied result. It does not prove a receipt row committed, a tenant predicate ran or an outbox entry was written. If authentication filters are part of the slice, test their behavior intentionally; if a test disables them, say so in its name. [[spring/mockmvc-security-filter-path|The security filter path]] deserves its own assertion, especially where method authorization is proxied.'),
  ('Make failures concrete','Stub the service to throw the domain exception used for a missing receipt. Assert the exception advice yields the agreed status and error shape. Send malformed JSON and a validation failure. Check the service was not called for invalid input. A focused slice should start quickly and fail on mapping drift, while a separate [[spring/command-rollback-proof|transaction test]] proves storage effects. Keep one test for each boundary rather than duplicating the same mocked happy path many times.')],code='@WebMvcTest(ReceiptController.class)\nclass ReceiptControllerSliceTest {\n    @Autowired MockMvc mvc;\n    @MockitoBean ReceiptService receiptService;\n\n    @Test void missingReceiptReturns404() throws Exception {\n        when(receiptService.loadReceipt("r-47")).thenThrow(new ReceiptMissingException());\n        mvc.perform(get("/api/receipts/r-47"))\n            .andExpect(status().isNotFound());\n    }\n}',language='java',cost='A slice starts fewer beans than a full application context, reducing setup time and memory. Mock behavior must be maintained as service contracts change; false confidence is the main cost.',mistakes=['Do not call a mocked controller slice a database integration test.','Do not omit security filters while claiming authorization coverage.','Do not duplicate a full-context test for every simple controller mapping.'],related=['spring/mockmvc-standalone-scope','spring/mockmvc-tests','spring/mockmvc-security-filter-path','spring/command-rollback-proof','spring/test-context-cache-shape'],backlink='spring/mockmvc-standalone-scope'),
 dict(slug='mockmvc-async-dispatch-proof',title='Spring MockMvc async dispatch: assert the final response after resumed handling',summary='A controller returning Callable or another async value starts servlet async processing; the first MockMvc result is not the completed HTTP response.',blocks=[
  ('Two phases of one request','A receipt export endpoint returns a Callable that produces a response later. MockMvc first sees the request enter async mode. The application then completes the computation and the servlet request is dispatched again so MVC can render or resolve an exception. A test that only asserts asyncStarted misses the final status, headers and body. Use asyncDispatch on the captured MvcResult and make the second assertion the HTTP contract. [[spring/mockmvc-tests|MockMvc]] still uses mock servlet objects, so this is not a real socket test.'),
  ('Test failure as well as success','If export generation throws after the initial return, the async dispatch is where an exception resolver can turn it into an error response. Assert the error shape there. Use an executor appropriate to the test: a direct executor can make a unit test deterministic but will not demonstrate production concurrency or rejection. [[spring/bounded-executor-rejection|Executor admission]] and [[spring/async-future-failure|background failure handling]] need their own tests.'),
  ('Keep waiting bounded','Set a test wait budget that covers the controlled calculation, not an open-ended sleep. A test should assert that async processing started before dispatch; otherwise a controller change to synchronous behavior may silently alter the boundary. For timeout behavior, test the configured MVC timeout and resulting response separately from the work cancellation policy. An async Servlet response can time out while underlying work continues unless that work is cancelled cooperatively.')],code='MvcResult pending = mvc.perform(get("/api/receipts/r-47/export"))\n    .andExpect(request().asyncStarted())\n    .andReturn();\nmvc.perform(asyncDispatch(pending))\n    .andExpect(status().isOk())\n    .andExpect(header().string("Content-Type", "application/pdf"));',language='java',cost='The test has two dispatch phases and one bounded wait. It does not measure thread-pool throughput or socket latency; those require executor and live-server checks.',mistakes=['Do not assert only asyncStarted and call the response verified.','Do not use Thread.sleep as the synchronization mechanism.','Do not assume a response timeout automatically stops the background calculation.'],related=['spring/mockmvc-tests','spring/async-future-failure','spring/bounded-executor-rejection','spring/restclient-loopback-test-boundary','spring/failure-layer-matrix'],backlink='spring/mockmvc-tests'),
 dict(slug='dynamic-property-source-lifecycle',title='Spring @DynamicPropertySource: bind test resources without stale cached values',summary='Runtime test properties supply ports and credentials, but their suppliers and shared ApplicationContext cache must follow the same resource lifecycle.',blocks=[
  ('Bind the resource actually started','A database container chooses a port at runtime. A static @DynamicPropertySource method can register a supplier for the JDBC URL, user and password after the container is available. The supplier is evaluated when the property is resolved, and runtime properties take precedence over @TestPropertySource and ordinary environment values. [[spring/testcontainers-service-connection-lifecycle|Service connections]] are another Boot integration path; choose one owner for the same property to avoid confusing overrides.'),
  ('Watch cache reuse','Spring caches ApplicationContexts by their test configuration shape, which includes runtime-property methods. If subclasses inherit one method but each uses a different external resource, a cached context can retain bindings from the first class. Keep the resource stable across classes that share a context, make configuration shapes distinct, or deliberately evict the context when values change. [[spring/test-context-cache-shape|Context cache shape]] explains why a static method name is not a guarantee that its supplied value stayed constant.'),
  ('Verify the endpoint of the connection','Log a non-secret database identity in the test, then query a marker row that exists only in the intended resource. Avoid printing passwords or full connection URLs with credentials. Stop one resource and ensure a later test does not keep using a stale pool. If several containers start in parallel, ensure each test class references its own server and cleanup does not race another class.')],code='@DynamicPropertySource\nstatic void receiptDatabase(DynamicPropertyRegistry properties) {\n    properties.add("spring.datasource.url", receiptPostgres::getJdbcUrl);\n    properties.add("spring.datasource.username", receiptPostgres::getUsername);\n    properties.add("spring.datasource.password", receiptPostgres::getPassword);\n}',language='java',cost='Supplier evaluation is cheap. Starting an external database and rebuilding contexts dominate runtime; careless cache eviction can multiply suite duration.',mistakes=['Do not register runtime properties for a resource that has not started.','Do not assume cached contexts refresh when an inherited supplier changes value.','Do not publish credentials while debugging the test database binding.'],related=['spring/testcontainers-service-connection-lifecycle','spring/test-context-cache-shape','spring/testcontainers-parallel-isolation','spring/boot-configtree-test-boundary','spring/datajpa-test-real-dialect'],backlink='spring/test-context-cache-shape'),
 dict(slug='sql-test-fixture-transaction-mode',title='Spring @Sql fixtures: decide whether setup commits outside the test rollback',summary='SQL setup can join a test transaction or commit in an isolated one; the choice changes what survives cleanup and what other connections can see.',blocks=[
  ('Fixture visibility is transactional','A receipt test decorated with @Transactional normally rolls back its work at the end. An @Sql fixture may run inside that transaction when a transaction manager is available. A service invoked on the same thread sees the setup row, but a separate HTTP request or worker connection may not see uncommitted setup. With @SqlConfig(transactionMode = ISOLATED), the script runs in its own transaction and commits before the test. [[spring/http-test-transaction-boundary|Client versus server transactions]] determine which mode a live-server test needs.'),
  ('Own teardown','An isolated fixture will not disappear when the test transaction rolls back. Give each test a unique receipt key, clean it deliberately or reset the disposable database. A cleanup script using isolated mode can run after the test, but it must not delete records still being used by a parallel test. [[spring/testcontainers-parallel-isolation|Parallel database isolation]] is a stronger choice when many tests share one server. Avoid broad DELETE statements against a database that may contain non-test data.'),
  ('Prove the desired semantics','Run a test that opens another connection and checks whether the fixture is visible before the test ends. Assert the row is gone after rollback for joined fixtures and remains until cleanup for isolated fixtures. The correct mode depends on whether the component under test uses the test thread or a separate transaction. Write that expectation in the test name so a future switch from MockMvc to a socket test does not silently invalidate it.')],code='@Sql(scripts = "/sql/receipt-seed.sql",\n     config = @SqlConfig(transactionMode = SqlConfig.TransactionMode.ISOLATED))\n@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)\nclass ReceiptHttpFixtureTest {\n    // The server request uses another transaction and sees committed seed data.\n}',language='java',cost='An isolated script adds a commit and cleanup work. Joined setup is cheaper and rollback-friendly, but cannot serve a different connection until committed.',mistakes=['Do not expect a server-side request to see uncommitted test-thread setup.','Do not expect isolated @Sql data to vanish with the test rollback.','Do not share fixed fixture keys across parallel tests without isolation.'],related=['spring/http-test-transaction-boundary','spring/testcontainers-parallel-isolation','spring/command-rollback-proof','spring/datajpa-test-flush-clear','spring/test-context-cache-shape'],backlink='spring/http-test-transaction-boundary'),
 dict(slug='dirtiescontext-cache-eviction',title='Spring @DirtiesContext: evict only a context a test truly changed',summary='Marking a context dirty closes and removes it from the test cache; use it for mutated container state, not ordinary database cleanup.',blocks=[
  ('What the annotation resets','A test replaces a singleton bean definition or changes a mutable configuration object that survives across test methods. @DirtiesContext tells the TestContext framework to remove that ApplicationContext from its static cache and close it. A later test with the same configuration gets a rebuilt context. This can prevent state leakage, but it does not erase an external database or queue. [[spring/test-context-cache-shape|Cache reuse]] is valuable only when contexts remain equivalent.'),
  ('Pick the narrow point','Apply the annotation to the method that dirtied the context when one test is responsible, or to a class when the whole class needs a fresh container. Before using it, ask whether the mutable singleton should instead be reset in an after-test hook or replaced with an immutable test collaborator. Database rows belong to transaction rollback, truncation or disposable-schema ownership, not context eviction. [[spring/testcontainers-parallel-isolation|A shared Testcontainer]] can outlive multiple contexts.'),
  ('Measure suite cost','Count context starts before and after the annotation and inspect which test class caused eviction. A full Boot context may start migrations, caches, clients and listeners again, so one broad class annotation can cost seconds repeatedly. In a parallel suite, shared static state can still race even if one context gets evicted. Verify a formerly leaked singleton value is absent in the next test and that external data cleanup is independent.')],code='@DirtiesContext(methodMode = DirtiesContext.MethodMode.AFTER_METHOD)\n@Test\nvoid changesGlobalReceiptPolicyForThisTestOnly() {\n    mutableReceiptPolicy.setLimit(47);\n    assertThat(receiptService.limit()).isEqualTo(47);\n}',language='java',cost='Eviction forces context construction and bean initialization on the next compatible test, often far costlier than clearing an in-memory field. It does not reset external infrastructure.',mistakes=['Do not use @DirtiesContext as a substitute for database cleanup.','Do not annotate every integration test by default.','Do not leave mutable static state behind and assume context eviction resets it.'],related=['spring/test-context-cache-shape','spring/testcontainers-parallel-isolation','spring/dynamic-property-source-lifecycle','spring/datajpa-test-flush-clear','spring/context-testing'],backlink='spring/context-testing'),
 dict(slug='restclient-mock-server-contract',title='Spring RestClient mock server: assert outgoing request shape before socket tests',summary='MockRestServiceServer can intercept a RestClient builder and verify requests without a network connection; it cannot prove transport failures.',blocks=[
  ('Intercept at the builder','A receipt gateway sends a POST with an idempotency key and JSON payload. Bind MockRestServiceServer to the same RestClient.Builder used to create the gateway client, register the expected method, path and header, then return a controlled response. This quickly catches a misplaced header or wrong URI. The mock request factory must be installed before build() creates the client; binding a different builder tests nothing. [[spring/restclient-loopback-test-boundary|A loopback socket test]] covers real HTTP framing and connection behavior.'),
  ('Separate response mapping from transport','Use mock responses for success, conflict and error JSON, and assert the gateway converts each into the right domain outcome. The mock server does not simulate DNS lookup, TLS, socket timeouts or connection pooling in the same way as the deployed client. A real mock web server can cover those paths with the actual HTTP stack. [[spring/failure-layer-matrix|Layered failure tests]] keep fast request-shape checks without overstating their evidence.'),
  ('Verify every expectation','Call mockServer.verify() after the gateway action so an expected request that never happened fails the test. Use distinct idempotency values and exact target paths, not a broad match that could accept the wrong customer. Keep secrets out of assertion failure text. If the application mutates a shared RestClient.Builder, create a fresh builder per test to avoid expectations leaking into another case.')],code='RestClient.Builder receiptBuilder = RestClient.builder().baseUrl(serviceBaseAddress);\nMockRestServiceServer mockServer = MockRestServiceServer.bindTo(receiptBuilder).build();\nRestClient receiptClient = receiptBuilder.build();\nmockServer.expect(requestTo(serviceBaseAddress + "/receipts/r-47"))\n    .andExpect(method(HttpMethod.GET))\n    .andRespond(withSuccess("{\\"status\\":\\"issued\\"}", MediaType.APPLICATION_JSON));\nReceiptSnapshot snapshot = gatewayUsing(receiptClient).load("r-47");\nmockServer.verify();',language='java',cost='No socket means fast, deterministic request matching. The tradeoff is missing transport behavior; keep a smaller live HTTP test suite for timeouts, TLS and connection reuse.',mistakes=['Do not bind the mock server to a builder different from the production client under test.','Do not omit verify() and assume every expectation ran.','Do not call this a test of the real network transport.'],related=['spring/restclient-loopback-test-boundary','spring/failure-layer-matrix','spring/mockmvc-tests','spring/boot-config-process-test-boundary','spring/security-authentication-vs-denial'],backlink='spring/restclient-loopback-test-boundary'),
 dict(slug='webtestclient-live-server-choice',title='Spring WebTestClient target: distinguish mock binding from a running port',summary='The same fluent assertions can run against a mock application context or a live server, but the evidence differs at the network and transaction boundaries.',blocks=[
  ('Binding defines the test','WebTestClient can bind directly to a controller or ApplicationContext, or to a running server. The first choices use mock request and response handling; bindToServer uses HTTP and a base URL. A receipt endpoint may pass a mock-bound test while a reverse proxy, connector setting or real cookie attribute fails in deployment. [[spring/mockmvc-tests|MockMvc]] has the same servlet mock boundary. Name the test by its binding mode so a passing result is not mistaken for a socket test.'),
  ('Use the running port for transport evidence','With a random-port Boot test, build WebTestClient against the injected local port. Assert status, headers and JSON, then inspect durable state through a separate database connection. The HTTP server runs the request in another thread and transaction, so a test-thread @Transactional rollback does not undo server writes. [[spring/http-test-transaction-boundary|That transaction split]] changes fixture setup and teardown. Keep request deadlines and response size bounded to avoid hanging the test suite.'),
  ('Keep mock checks fast','Use context-bound tests for serialization, status mapping and controller validation. Reserve live-server tests for representative connector, security and transaction behavior, and verify any proxy-specific behavior in a deployment environment. [[spring/failure-layer-matrix|The failure-layer matrix]] prevents one large HTTP test from becoming the only evidence for every layer. Do not switch binding modes mid-test and expect the same database visibility rules.')],code='WebTestClient client = WebTestClient.bindToServer()\n    .baseUrl(localServerBaseAddress)\n    .build();\nclient.get().uri("/api/receipts/r-47").exchange()\n    .expectStatus().isOk()\n    .expectBody().jsonPath("$.status").isEqualTo("issued");',language='java',cost='A live server adds startup, socket and serialization work to each scenario. Mock-bound tests are faster but cannot establish connector or cross-thread transaction behavior.',mistakes=['Do not label a context-bound client test end-to-end HTTP.','Do not expect test-thread rollback to undo live-server writes.','Do not use a fixed port that collides with another parallel test process.'],related=['spring/mockmvc-tests','spring/http-test-transaction-boundary','spring/restclient-loopback-test-boundary','spring/failure-layer-matrix','spring/testcontainers-parallel-isolation'],backlink='spring/failure-layer-matrix'),
 dict(slug='preemptive-test-timeout-transaction',title='Spring transactional tests: preemptive timeouts can escape rollback',summary='Spring binds a test-managed transaction to the test thread; a preemptive timeout that runs the body on another thread can commit real writes.',blocks=[
  ('The rollback assumption breaks','A receipt integration test is annotated @Transactional and expects its insert to roll back after the method. A preemptive timeout helper may execute the assertion body in a separate worker thread. That worker does not inherit the test-managed transaction bound to the original thread, so service calls can open and commit their own transactions. The outer test rollback still occurs, but it rolls back the wrong thread’s empty work. [[spring/transaction-thread-boundary|Transaction thread ownership]] is the core issue.'),
  ('Use a safe timing strategy','Prefer a non-preemptive timing assertion for a short, deterministic block, or use a test framework timeout mode that runs the test body on the same thread. If the operation truly hangs, enforce a database statement or client timeout at the component boundary rather than moving a transactional test body to an untracked thread. Verify the chosen JUnit timeout mode in the project version. [[spring/transaction-timeout-outer-scope|Application transaction timeouts]] are separate from test runner deadlines.'),
  ('Prove cleanup from outside','After the test completes, open a new connection and assert the unique receipt key is absent. This catches a committed write that in-test assertions miss. Do the check with a disposable database so a failure can be inspected safely. If a real HTTP request is involved, the server already runs on another thread, regardless of timeout style; [[spring/http-test-transaction-boundary|live-server writes]] need deliberate cleanup.')],code='@Transactional\n@Test\nvoid receiptWriteRollsBackOnTestThread() {\n    assertTimeout(Duration.ofSeconds(7), () -> {\n        receiptService.issueReceipt(commandWithReference("r-47"));\n    });\n}\n// Avoid assertTimeoutPreemptively around this transaction-bound body.',language='java',cost='A same-thread timing assertion cannot forcibly stop a hung operation, so component-level timeouts are still necessary. It preserves rollback semantics and avoids leaking committed test rows.',mistakes=['Do not wrap a transactional test body in assertTimeoutPreemptively.','Do not infer rollback from an assertion made before the test transaction ends.','Do not assume @Transactional covers a live HTTP server request on another thread.'],related=['spring/transaction-thread-boundary','spring/http-test-transaction-boundary','spring/transaction-timeout-outer-scope','spring/command-rollback-proof','spring/testcontainers-parallel-isolation'],backlink='spring/transaction-thread-boundary'),
]

titles={path:row['title'] for path,row in by_path.items()}
titles.update({'spring/'+item['slug']:item['title'] for item in lessons})
for number,item in enumerate(lessons):
    path='spring/'+item['slug']
    assert path not in by_path,path
    for target in item['related']: assert target in titles,(path,target)
    body='<p>'+prose(item['summary'])+'</p>'
    for heading,content in item['blocks']: body+='<h2>'+html.escape(heading)+'</h2><p>'+prose(content)+'</p>'
    body+='<h2>Implementation contract</h2><pre><code class="language-'+item['language']+'">'+html.escape(item['code'],quote=False)+'</code></pre>'
    body+='<h2>Cost and verification</h2><p>'+prose(item['cost'])+'</p>'
    body+='<h3>Common Mistakes</h3><ul>'+''.join('<li>'+prose(mistake)+'</li>' for mistake in item['mistakes'])+'</ul>'
    body+='<h2>Read next</h2><p>'+', '.join('<a href="/'+target+'">'+html.escape(titles[target])+'</a>' for target in item['related'])+'.</p>'
    row=copy.deepcopy(by_path['spring/component-scan-vs-bean'])
    row.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL,'https://aitrove.in/'+path)),path=path,title=item['title'],summary=item['summary'],body=body,subject='spring-testing',tags=['spring','spring-testing',item['slug']],sort_order=6400+number,published_at=stamp,created_at=stamp,updated_at=stamp)
    row['data']={'subject_root':'spring/spring-boot','section_path':'spring/testing','kind':'tutorial','content_format':'html','seo_ready':True,'reading_minutes':max(4,round(len(re.sub(r'<[^>]+>',' ',body).split())/150)),'author_path':'authors/aitrove-editorial','framework_version':'Spring Boot 4 / Spring Framework 7 where relevant','java_version':'21 or later','verification_suite':'Spring Test API contract review; snippets require an application-specific model','related':[{'path':target,'title':titles[target]} for target in item['related']]}
    rows.append(row);by_path[path]=row
hub=by_path['spring/testing']
new_paths=['spring/'+item['slug'] for item in lessons]
hub['data']['modules'].append({'title':'Test slice and transaction boundaries','summary':'MVC slices, async dispatch, runtime properties, SQL fixture commits, context eviction, client stubs, live-server calls and test timeouts.','lessons':new_paths})
hub['body']+='<h2>Test slice and transaction boundaries</h2><ul>'+''.join('<li><a href="/'+path+'">'+html.escape(titles[path])+'</a></li>' for path in new_paths)+'</ul>'
hub['updated_at']=stamp
parent=by_path['spring/spring-boot']
parent['body']+='<h2>Spring test isolation</h2><p><a href="/spring/testing">Testing</a> now covers <a href="/spring/webmvctest-slice-collaborators">MVC slices</a>, <a href="/spring/sql-test-fixture-transaction-mode">SQL fixture transaction modes</a> and <a href="/spring/preemptive-test-timeout-transaction">preemptive timeout rollback risk</a>.</p>'
parent['updated_at']=stamp
for item in lessons:
    source,target=item['backlink'],'spring/'+item['slug']
    entry=by_path[source]
    entry['body']+='<h2>Related test contract</h2><p><a href="/'+target+'">'+html.escape(titles[target])+'</a>.</p>'
    entry['updated_at']=stamp
for source,target in [
 ('spring/mockmvc-tests','spring/webmvctest-slice-collaborators'),
 ('spring/async-future-failure','spring/mockmvc-async-dispatch-proof'),
 ('spring/testcontainers-service-connection-lifecycle','spring/dynamic-property-source-lifecycle'),
 ('spring/testcontainers-parallel-isolation','spring/sql-test-fixture-transaction-mode'),
 ('spring/test-context-cache-shape','spring/dirtiescontext-cache-eviction'),
 ('spring/boot-config-process-test-boundary','spring/restclient-mock-server-contract'),
 ('spring/http-test-transaction-boundary','spring/webtestclient-live-server-choice'),
 ('spring/command-rollback-proof','spring/preemptive-test-timeout-transaction'),
]:
    entry=by_path[source]
    entry['body']+='<h2>Related test contract</h2><p><a href="/'+target+'">'+html.escape(titles[target])+'</a>.</p>'
    entry['updated_at']=stamp
fixture.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print(f'Added {len(lessons)} Spring testing lessons; {len(rows)} total fixture records')
